head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.prevRow = -1;

// TB_BC120    지표종류    표준지표구분코드
// 는 메타이므로 화면에서 삭제

// TB_BC130    지표발행기관    지표기관    TBLD_B_INDIC_INST
// 만 구현한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "지표발행기관"));
        await scwin.ins_search();
        //    frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_save_OnFail = function() {
    try {
        alert_tr_error(trs_save);
        refresh();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05200.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.ins_process("02");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    try {
        await scwin.ins_process("03");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid1_OnClick
 * @description grd_Grid1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid1_OnClick = async function(row, colid) {
    try {
        let INDIC_ISUR_CD = dts_List.getCellData(row, "INDIC_ISUR_CD");
        await scwin.ins_HistSearch(INDIC_ISUR_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.grd_Grid1_OnClick" });
    }
};

/**
 * @method
 * @name dts_HistList_OnLoadCompleted
 * @description dts_HistList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_HistList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_HistList.errorMsg) {
            await $c.win.alert(dts_HistList.errorMsg);
        } else {
            txb_TotalCnt2.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.dts_HistList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_HistList_OnLoadError
 * @description dts_HistList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_HistList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_HistList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.dts_HistList_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_new_onclick = function() {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05200.btn_new_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = async function(row) {
    try {
        dts_List.undoRow(scwin.prevRow);
        scwin.prevRow = row;
        fn_CtrlBtn("update");
        let INDIC_ISUR_CD = dts_List.getCellData(row, "INDIC_ISUR_CD");
        await scwin.ins_HistSearch(INDIC_ISUR_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.ins_search();
        await scwin.ins_HistSearch("");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS05200.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_INDIC_ISUR_CD_onkeyup
 * @description txb_INDIC_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_INDIC_ISUR_CD_onkeyup = function() {
    try {
        fn_DelChar(this);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS05200.txb_INDIC_ISUR_CD_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 지표발행기관 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_HistSearch
 * @description 지표발행기관 내역 조회한다.
 * @param {String} INDIC_ISUR_CD INDIC_ISUR_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_HistSearch = async function(INDIC_ISUR_CD) {
    const sbmOptions = {
        id : "sbm_dts_HistList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_HistList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_process
 * @description 지표발행기관 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} screenProcsTpCd screenProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_process = async function(screenProcsTpCd) {
    // alert("dts_Out.Text " +dts_Out.Text);
    // alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));

    if (!$c.cp.isModified(dts_List)) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return;
    }
    if (txb_INDIC_ISUR_CD.getValue().length === 3) {

    } else {
        await $c.win.alert("지표발행기관코드는 3자리 입니다.");
        txb_INDIC_ISUR_CD.focus();
        return;
    }
    if (screenProcsTpCd === "02") {
        // 등록시 중복체크
        if (scwin.dup() === false) {
            await $c.win.alert("지표발행기관코드 중복입니다.");
            txb_INDIC_ISUR_CD.focus();
            return;
        }
    }
    if (txb_INDIC_ISUR_CD.getValue() === "" || txb_INDIC_ISUR_CD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관코드"));
        txb_INDIC_ISUR_CD.focus();
        return;
    }
    if (txb_INDIC_ISUR_NM.getValue() === "" || txb_INDIC_ISUR_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관명"));
        txb_INDIC_ISUR_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_INDIC_ISUR_NM, 80, "지표발행기관명")) {
        // txb_INDIC_ISUR_NM.value = "";
        txb_INDIC_ISUR_NM.focus();
        return false;
    }
    if (edt_INDIC_ISUR_ENG_NM.getValue() === "" || edt_INDIC_ISUR_ENG_NM.text.indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관영문명"));
        edt_INDIC_ISUR_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(edt_INDIC_ISUR_ENG_NM, 60, "지표발행기관영문명")) {
        // edt_INDIC_ISUR_ENG_NM.text = "";
        edt_INDIC_ISUR_ENG_NM.focus();
        return false;
    }
    if (edt_INDIC_ISUR_ENG_ABBRV.getValue() === "" || edt_INDIC_ISUR_ENG_ABBRV.text.indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관영문약명"));
        edt_INDIC_ISUR_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(edt_INDIC_ISUR_ENG_ABBRV, 40, "지표발행기관영문약명")) {
        // edt_INDIC_ISUR_ENG_ABBRV.text = "";
        edt_INDIC_ISUR_ENG_ABBRV.focus();
        return false;
    }
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/OrgInfoAction.do",
        ref : "dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name new
 * @description 신규 등록
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    dts_List.insertRow();
    // dts_List.NameValue(dts_List.RowPosition,"ISUR_CD") = param1;
    fn_CtrlBtn("insert");
    cmb_ACTIV_YN.setSelectedIndex(0);
};

/**
 * @method
 * @name dup
 * @description 지표발행기관코드 중복검사
 * @returns {void}
 * @hidden N
 */
scwin.dup = function() {
    let dupcnt = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "INDIC_ISUR_CD") === txb_INDIC_ISUR_CD.getValue()) {
            dupcnt++;
        }
    }
    // alert("dupcnt " +dupcnt);
    if (Number(dupcnt) < 2) {
        return true;
    } // 중복아님
    else {
        return false;
    } // 중복

};
